// Activity defines model for Activity.
type Activity struct {
	// Contributions What the activity brings, now, to each challenge where it counts;
	// possibly empty. A deleted challenge never appears.
	Contributions   []ActivityContribution `json:"contributions"`
	DistanceMeters  *int                   `json:"distance_meters"`
	DurationSeconds int                    `json:"duration_seconds"`

	// ElevationGainMeters Positive elevation gain in meters; null when not entered.
	ElevationGainMeters *int               `json:"elevation_gain_meters"`
	Id                  openapi_types.UUID `json:"id"`

	// Locked True once the week of the activity is locked in a challenge where
	// it counts, at 7 am, local time of the challenge, on the first day
	// of the next week, or was already locked when the user left a
	// challenge (abandoned or excluded): it can no longer be changed nor
	// deleted.
	Locked bool `json:"locked"`

	// PaceSecondsPerKm Pace in seconds per kilometer, computed; null without distance.
	PaceSecondsPerKm *float64 `json:"pace_seconds_per_km"`

	// Repetitions Every repetitions of the activity by exercise, sorted by
	// exercise, those of an exercise no challenge offers any more
	// included; absent when none.
	Repetitions *[]ActivityRepetitions `json:"repetitions,omitempty"`
	Source      ActivitySource         `json:"source"`

	// SpeedMps Speed in meters per second, computed; null without distance.
	SpeedMps  *float64 `json:"speed_mps"`
	SportCode string   `json:"sport_code"`

	// SportLabel Label of the sport `other`, cleaned; null for the others.
	SportLabel *string   `json:"sport_label"`
	StartedAt  time.Time `json:"started_at"`
}

// ActivitySource defines model for Activity.Source.
type ActivitySource string

// ActivityContribution defines model for ActivityContribution.
type ActivityContribution struct {
	ChallengeId    openapi_types.UUID `json:"challenge_id"`
	ChallengeTitle string             `json:"challenge_title"`

	// DistanceMeters The distance brought to the cumulative distance category: the
	// distance times the factor of the sport in this challenge, rounded
	// to the meter (half up) as the ranking rounds a total. Null when
	// the challenge has no cumulative distance category, the sport no
	// factor in this challenge, or the activity no distance. The ranking rounds the total once, so it may differ by
	// a meter or so from the sum of these values.
	DistanceMeters *int `json:"distance_meters"`

	// DurationSeconds The duration brought to the cumulative time category.
	DurationSeconds int `json:"duration_seconds"`
}

// ActivityCreate defines model for ActivityCreate.
type ActivityCreate struct {
	// DistanceMeters Required or refused according to the sport's `distance_mode`.
	DistanceMeters  *int `json:"distance_meters,omitempty"`
	DurationSeconds int  `json:"duration_seconds"`

	// ElevationGainMeters Positive elevation gain in meters, optional; it counts for the
	// `cumulative_elevation` category and the `weekly_elevation`
	// criterion of the `points` category, and for nothing else (no
	// badge). Refused (`elevation_not_allowed`)
	// when the sport's `elevation_allowed` is false or the activity has
	// no distance. On a change, leaving it out removes it.
	ElevationGainMeters *int `json:"elevation_gain_meters,omitempty"`

	// Repetitions Repetitions by exercise, optional; they count for the elimination
	// by repetitions only. Each exercise once, and one of a challenge of
	// the user with an elimination by repetitions, whose reference
	// sport is `sport_code`, where they are an active participant and
	// whose window holds `started_at` (`unknown_exercise` otherwise).
	// A change replaces them all, as the other fields: left out, they
	// are removed; those of an exercise already on the activity are
	// kept even when no challenge offers it any more.
	Repetitions *[]ActivityRepetitions `json:"repetitions,omitempty"`

	// SportCode Code of a sport of the catalogue (`GET /api/v1/sports`): a
	// lowercase letter, then lowercase letters, digits or `_`, as the
	// catalogue allows (constraint `sports_code_check`).
	//
	//
	// Example: run
	SportCode string `json:"sport_code"`

	// SportLabel Free label of the sport `other`, required for it and refused for
	// the others: 2 to 40 characters once spaces are cleaned, 2 of them
	// visible (the kept formatting characters below do not count), no
	// control character, no line or
	// paragraph separator (U+2028, U+2029), no invisible or bidirectional
	// formatting character (Unicode Cf, such as U+200B or U+202E) but
	// U+200C, U+200D, U+200E, U+200F and the tags of flags (U+E0020 to
	// U+E007F).
	SportLabel *string `json:"sport_label,omitempty"`

	// StartedAt Start of the activity; never before 2000-01-01T00:00:00Z, and the
	// activity is entered once done: its end (`started_at` plus
	// `duration_seconds`) is never in the future either (5 minutes of
	// tolerance).
	StartedAt time.Time `json:"started_at"`
}

